<script lang="ts">
  import { onMount } from 'svelte';
  import { useStudioModuleContext } from '@hpd-research/hpd-studio-core';
  import type { GatewayRevisionId } from '@hpd/gateway-client';
  import type { GatewayManagedWorkflowController, GatewayManagedWorkflowSnapshot } from './managed-workflows.ts';
  import type { GatewayOperationsController, GatewayOperationsSnapshot } from './operations.ts';
  const moduleContext=useStudioModuleContext();
  const controller=requireValue(moduleContext.get<GatewayManagedWorkflowController>('gateway-managed-workflow-controller'));
  const operations=requireValue(moduleContext.get<GatewayOperationsController>('gateway-operations-controller'));
  let managed:GatewayManagedWorkflowSnapshot=$state(controller.snapshot());
  let operating:GatewayOperationsSnapshot=$state(operations.snapshot());
  let description=$state('');
  let compareLeft=$state('');
  let compareRight=$state('');
  let importText=$state('');
  let importSource=$state('studio-import');
  let backupSink=$state('');let backupLabel=$state('');let purgeIds=$state('');let purgeCategory=$state<'RevisionContent'|'ValidationContent'|'ActivationOutcomeHistory'|'AuditHistory'>('RevisionContent');
  onMount(()=>{const first=controller.subscribe(next=>managed=next);const second=operations.subscribe(next=>operating=next);return()=>{first();second();};});
  function requireValue<T>(value:T|undefined):T{if(value===undefined)throw new Error('Gateway managed workflow context is unavailable.');return value;}
  async function select(id:string){await controller.selectRevision(id as GatewayRevisionId);}
  async function compare(){if(compareLeft&&compareRight)await controller.compare(compareLeft as GatewayRevisionId,compareRight as GatewayRevisionId);}
</script>

<main class="min-h-0 p-4 sm:p-6 lg:p-8">
 <div class="mx-auto grid w-full max-w-[110rem] gap-4">
  <header><p class="studio-label">HPD Gateway Studio · Operate</p><h1 class="text-3xl font-extrabold">Governed revisions and activation</h1><p class="mt-2 max-w-3xl text-sm text-studio-muted">Server truth remains separate from authored, desired, delivered, active, and effective state. A 202 response means accepted delivery only.</p></header>
  {#if managed.context===null}<section class="studio-panel p-4" role="status"><h2 class="font-bold">Explicit target required</h2><p class="text-sm text-studio-muted">Choose a namespace and target from Gateway Overview. Studio performs no target discovery.</p></section>
  {:else}
   <section class="studio-panel grid gap-3 p-4"><div class="flex flex-wrap items-center justify-between gap-3"><div><p class="studio-label">Target</p><p class="font-mono text-sm">{managed.context.namespaceId} / {managed.context.targetNodeId}</p></div><div class="flex gap-2"><button class="studio-button studio-button-sm" onclick={()=>controller.loadRevisions(false)}>Refresh revisions</button><button class="studio-button studio-button-sm" onclick={()=>controller.loadActivationHistory()}>Refresh activation history</button></div></div></section>
   <div class="grid gap-4 xl:grid-cols-[minmax(18rem,0.8fr)_minmax(25rem,1.2fr)]">
    <section class="studio-panel grid content-start gap-3 p-4"><div><h2 class="font-bold">Immutable revisions</h2><p class="text-xs text-studio-muted">{managed.revisions.length} loaded{managed.revisionsHaveMore?' · more available':''}. Filtering applies only to loaded rows.</p></div>{#each managed.revisions as revision}<button class="studio-focus-ring rounded-studio border border-studio-line p-3 text-left" onclick={()=>select(revision.revisionId)}><strong>{revision.revisionId}</strong><span class="mt-1 block text-xs text-studio-muted">{revision.sourceKind} · {revision.acceptedAt??'time unavailable'}</span></button>{/each}{#if managed.revisionsHaveMore}<button class="studio-button" onclick={()=>controller.loadRevisions(true)}>Load next page</button>{/if}</section>
    <section class="grid content-start gap-4">
     <section class="studio-panel grid gap-3 p-4"><h2 class="font-bold">Selected revision</h2>{#if managed.selectedRevision}<p class="studio-text-safe font-mono text-sm">{managed.selectedRevision.revisionId}</p><p class="text-sm">{managed.selectedRevision.description??'No description'}</p><div class="flex flex-wrap gap-2"><button class="studio-button studio-button-sm" onclick={()=>controller.exportRevision(managed.selectedRevision!.revisionId)}>Export complete configuration</button><button class="studio-button studio-button-sm" onclick={()=>controller.openActivation('activate',managed.selectedRevision!.revisionId,description)}>Review activation</button><button class="studio-button studio-button-sm" onclick={()=>controller.openActivation('rollback',managed.selectedRevision!.revisionId,description)}>Review rollback</button></div><label class="grid gap-1 text-sm">Optional description<input class="rounded-studio border border-studio-line bg-studio-panel-raised p-2" maxlength="1024" bind:value={description}/></label>{:else}<p class="text-sm text-studio-muted">Select a revision to inspect metadata. Only Export supplies a complete candidate.</p>{/if}</section>
     {#if managed.exported}<section class="studio-panel grid gap-2 p-4"><h2 class="font-bold">Exported configuration</h2><p class="text-xs text-studio-muted">Read-only until explicitly opened as a new authored candidate.</p><button class="studio-button" onclick={()=>controller.openExportAsAuthored()}>Open as new authored candidate</button></section>{/if}
     <section class="studio-panel grid gap-2 p-4"><h2 class="font-bold">Server revision comparison</h2><div class="grid gap-2 sm:grid-cols-2"><input aria-label="Left revision" bind:value={compareLeft}/><input aria-label="Right revision" bind:value={compareRight}/></div><button class="studio-button justify-self-start" onclick={compare}>Compare immutable revisions</button>{#if managed.comparison}<p class="text-sm">{managed.comparison.equivalent?'Equivalent':'Different'} · {managed.comparison.differences.length} retained differences{managed.comparison.isTruncated?' · truncated':''}</p>{/if}</section>
    </section>
   </div>
   <section class="studio-panel grid gap-3 p-4"><h2 class="font-bold">Activation timeline</h2><div class="grid gap-4 lg:grid-cols-2"><div><h3 class="font-semibold">Intents</h3>{#each managed.activationIntents as item}<p class="studio-text-safe text-sm"><strong>{item.intentId}</strong> → {item.revisionId}</p>{/each}</div><div><h3 class="font-semibold">Outcomes</h3>{#each managed.activationOutcomes as item}<p class="studio-text-safe text-sm"><strong>{item.activationIntentId}</strong> · {item.kind}</p>{/each}</div></div>{#if managed.intentsHaveMore||managed.outcomesHaveMore}<button class="studio-button justify-self-start" onclick={()=>controller.loadActivationHistory()}>Load remaining available pages</button>{/if}</section>
   <section class="studio-panel grid gap-4 p-4"><div class="flex flex-wrap items-center justify-between gap-2"><div><h2 class="font-bold">Namespace audit</h2><p class="text-xs text-studio-muted">{operating.audit.length} loaded{operating.auditHasMore?' · more available':''}{operating.auditStale?' · stale':''}. Actor identity records attribution, not authorization.</p></div><button class="studio-button studio-button-sm" onclick={()=>operations.loadAudit(operating.audit.length>0)}>{operating.auditLoading?'Loading…':'Load audit'}</button></div><div class="grid gap-2">{#each operating.audit as item}<article class="rounded-studio border border-studio-line p-3"><div class="flex flex-wrap items-center justify-between gap-2"><strong>{item.operation}</strong><span class="studio-badge">{item.resultCode}</span></div><dl class="mt-2 grid gap-2 text-xs sm:grid-cols-2 xl:grid-cols-3"><div><dt class="studio-label">Audit identity</dt><dd class="studio-text-safe font-mono">{item.auditId}</dd></div><div><dt class="studio-label">Actor identity</dt><dd class="studio-text-safe font-mono">{item.actorId}</dd></div><div><dt class="studio-label">Correlation identity</dt><dd class="studio-text-safe font-mono">{item.correlationId}</dd></div><div><dt class="studio-label">Subject identity</dt><dd class="studio-text-safe font-mono">{item.subjectId}</dd></div><div><dt class="studio-label">Recorded at</dt><dd>{item.recordedAt??'time unavailable'}</dd></div><div><dt class="studio-label">Result</dt><dd>{item.resultCode}</dd></div></dl></article>{/each}</div>{#if operating.auditHasMore}<button class="studio-button studio-button-sm justify-self-start" onclick={()=>operations.loadAudit(false)}>Load more audit</button>{/if}</section>
   <section class="studio-panel grid gap-4 p-4"><div><h2 class="font-bold">Administration</h2><p class="text-sm text-studio-muted">Provision, backup, and purge are explicit identified workflows. A 202 response is not provider completion.</p></div><div class="grid gap-3 lg:grid-cols-3"><article class="rounded-studio border border-studio-line p-3"><h3 class="font-semibold">Provision</h3><p class="text-xs text-studio-muted">Attempts ownership for the selected explicit target without proving it is free.</p><button class="studio-button studio-button-sm mt-3" onclick={()=>operations.openProvisionReview()}>Review provision</button></article><article class="rounded-studio border border-studio-line p-3"><h3 class="font-semibold">Backup</h3><input aria-label="Backup sink" placeholder="sink-name" bind:value={backupSink}/><input aria-label="Artifact label" placeholder="optional-label" bind:value={backupLabel}/><button class="studio-button studio-button-sm mt-3" onclick={()=>operations.openBackupReview(backupSink,backupLabel||undefined)}>Review backup</button></article><article class="rounded-studio border border-studio-line p-3"><h3 class="font-semibold">Purge</h3><select bind:value={purgeCategory}><option>RevisionContent</option><option>ValidationContent</option><option>ActivationOutcomeHistory</option><option>AuditHistory</option></select><textarea aria-label="Purge resource IDs" placeholder="One sorted ID per line" bind:value={purgeIds}></textarea><button class="studio-button studio-button-sm mt-3" onclick={()=>operations.openPurgeReview(purgeCategory,purgeIds.split('\n').filter(Boolean))}>Review purge</button></article></div></section>
   {#if operating.review}<section class="studio-panel grid gap-3 border-studio-warning-soft p-4" aria-live="polite"><div><p class="studio-label">Administrative review</p><h2 class="font-bold">{operating.review.kind} · {operating.review.phase}</h2></div><dl class="grid gap-2 text-sm sm:grid-cols-2"><div><dt class="studio-label">Namespace</dt><dd>{operating.review.namespaceId}</dd></div><div><dt class="studio-label">Expected consequence</dt><dd>{operating.review.expectedStatus} · {operating.review.kind==='provision'?'ownership only':'accepted administration, not completion'}</dd></div><div><dt class="studio-label">Idempotency identity</dt><dd class="studio-text-safe font-mono">{operating.review.idempotencyKey}</dd></div><div><dt class="studio-label">Correlation</dt><dd class="studio-text-safe font-mono">{operating.review.correlationId}</dd></div>{#if operating.review.operationId}<div><dt class="studio-label">Operation identity</dt><dd class="studio-text-safe font-mono">{operating.review.operationId}</dd></div>{/if}{#if operating.review.kind==='backup'}<div><dt class="studio-label">Backup sink</dt><dd class="studio-text-safe font-mono">{operating.review.sinkName}</dd></div><div><dt class="studio-label">Artifact label</dt><dd class="studio-text-safe font-mono">{operating.review.artifactLabel??'No label'}</dd></div>{/if}{#if operating.review.kind==='purge'}<div><dt class="studio-label">Purge category</dt><dd>{operating.review.purgeCategory}</dd></div><div><dt class="studio-label">Resource count</dt><dd>{operating.review.resourceIds.length}</dd></div>{/if}</dl>{#if operating.review.kind==='purge'}<div><p class="studio-label">Complete reviewed resource set</p><ol class="mt-1 max-h-64 overflow-auto rounded-studio border border-studio-line p-3 font-mono text-xs">{#each operating.review.resourceIds as resourceId,index}<li class="studio-text-safe">{index+1}. {resourceId}</li>{/each}</ol></div>{/if}{#if operating.review.kind==='purge'&&operating.review.phase==='reviewing'}<label class="grid gap-1 text-sm">Type namespace to confirm<input value={operating.review.confirmationPhrase} oninput={(event)=>operations.setConfirmationPhrase(event.currentTarget.value)}/></label>{/if}{#if operating.review.operation}<p class="text-sm"><strong>{operating.review.operation.state}</strong> · {operating.review.operation.code}</p>{#if operating.review.operation.artifactReference}<p class="studio-text-safe font-mono text-sm">{operating.review.operation.artifactReference}</p>{/if}{/if}<div class="flex flex-wrap gap-2">{#if operating.review.phase==='reviewing'}<button class="studio-button" onclick={()=>operations.requestConfirmation()}>Continue to confirmation</button>{:else if operating.review.phase==='confirming'}<button class="studio-button" onclick={()=>operations.execute()}>Confirm {operating.review.kind}</button>{:else if operating.review.phase==='failed'&&operating.review.transportAmbiguous}<button class="studio-button" onclick={()=>operations.retryExact()}>Retry exact identified operation</button>{:else if operating.review.operation}<button class="studio-button studio-button-sm" onclick={()=>operations.refreshAdministrativeOperation()}>Refresh operation</button>{/if}<button class="studio-button studio-button-sm" disabled={operating.review.phase==='executing'} onclick={()=>operations.closeReview()}>Close</button></div></section>{/if}
   <section class="studio-panel grid gap-3 p-4"><div><h2 class="font-bold">Import a complete candidate</h2><p class="text-sm text-studio-muted">The preview remains workflow-local. Import and import-and-activate are distinct governed commands and never silently replace the editor.</p></div><label class="grid gap-1 text-sm">Bounded source identity<input class="rounded-studio border border-studio-line bg-studio-panel-raised p-2" bind:value={importSource}/></label><label class="grid gap-1 text-sm">Gateway configuration JSON<textarea class="min-h-48 rounded-studio border border-studio-line bg-studio-panel-raised p-2 font-mono text-xs" bind:value={importText}></textarea></label><div class="flex flex-wrap gap-2"><button class="studio-button" disabled={managed.workflow!==null} onclick={()=>controller.openImport('import',importText,importSource,description)}>Review import</button><button class="studio-button" disabled={managed.workflow!==null} onclick={()=>controller.openImport('import-and-activate',importText,importSource,description)}>Review import and activate</button></div></section>
   {#if managed.workflow}<section class="studio-panel grid gap-3 border-studio-warning-soft p-4" aria-live="polite">
    <div><p class="studio-label">Mutation review</p><h2 class="font-bold">{managed.workflow.kind} · {managed.workflow.phase}</h2></div>
    <dl class="grid gap-3 text-sm sm:grid-cols-2 xl:grid-cols-3">
     <div><dt class="studio-label">Authority target</dt><dd class="studio-text-safe font-mono">{managed.workflow.namespaceId} / {managed.workflow.targetNodeId}</dd></div>
     <div><dt class="studio-label">Exact consequence</dt><dd>{managed.workflow.expectedSuccessStatus} · {managed.workflow.expectedSuccessStatus===201?'Accepted immutable revision':'Accepted durable delivery, not activation success'}</dd></div>
     <div><dt class="studio-label">Proposed identity</dt><dd class="studio-text-safe font-mono">{managed.workflow.proposedIdentity}</dd></div>
     <div><dt class="studio-label">Current desired</dt><dd class="studio-text-safe font-mono">{managed.workflow.baseDesiredRevisionId??'Authoritatively not observed'}{managed.workflow.baseDesiredCandidateId?` · ${managed.workflow.baseDesiredCandidateId}`:''}{managed.workflow.baseDesiredActivationIntentId?` · ${managed.workflow.baseDesiredActivationIntentId}`:''}</dd></div>
     <div><dt class="studio-label">CAS</dt><dd>{managed.workflow.desiredPrecondition?.kind??'Not applicable'}</dd></div>
     <div><dt class="studio-label">Idempotency identity</dt><dd class="studio-text-safe font-mono">{managed.workflow.idempotencyKey}</dd></div>
     <div><dt class="studio-label">Authored generation</dt><dd>{managed.workflow.baseEditGeneration?.toString()??'Not an authored submission'}</dd></div>
     <div><dt class="studio-label">Authored source</dt><dd class="studio-text-safe font-mono">{managed.workflow.baseSourceSha256??'Workflow-local import or selected revision'}</dd></div>
     <div><dt class="studio-label">Validation transport</dt><dd class="studio-text-safe font-mono">{managed.workflow.baseValidationTransportSha256??'Not applicable'}</dd></div>
     <div><dt class="studio-label">Capability snapshot</dt><dd class="studio-text-safe font-mono">{managed.workflow.baseCapabilitySnapshotIdentity??'Not applicable'}</dd></div>
     <div><dt class="studio-label">Difference evidence</dt><dd>{managed.workflow.semanticDiffSource} · {managed.workflow.semanticDifferenceCount} retained{managed.workflow.semanticDiffTruncated?` · ${managed.workflow.semanticDiffTruncated} truncated`:''}</dd></div>
     <div><dt class="studio-label">Command correlation</dt><dd class="studio-text-safe font-mono">{managed.workflow.commandCorrelationId}</dd></div>
    </dl>
    <p class="text-sm text-studio-muted">Confirmation does not imply execution. Accepted delivery does not imply Delivered, Active, Effective, or Serving Ready.</p>
    <div class="flex flex-wrap gap-2">{#if managed.workflow.phase==='Reviewing'}<button class="studio-button" onclick={()=>controller.requestConfirmation()}>Continue to explicit confirmation</button>{:else if managed.workflow.phase==='Confirming'}<button class="studio-button" onclick={()=>controller.execute()}>Confirm {managed.workflow.kind}</button>{:else if managed.workflow.phase==='Executing'}<button class="studio-button" onclick={()=>controller.cancelExecution()}>Cancel observation</button>{:else if managed.workflow.phase==='Failed'&&managed.workflow.result?.kind==='transport'}<button class="studio-button" onclick={()=>controller.retryExact()}>Retry exact identified command</button>{/if}<button class="studio-button studio-button-sm" disabled={managed.workflow.phase==='Executing'} onclick={()=>controller.closeWorkflow()}>Close</button></div>
    {#if managed.workflow.result}<p class="text-sm" role="status">{managed.workflow.result.code}{managed.workflow.result.duplicate?' · exact duplicate replay':''}</p>{/if}
   </section>{/if}
  {/if}
 </div>
</main>
